using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

[McpServerToolType]
public class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // Constructor params are resolved from DI automatically.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}&current=temperature_2m,wind_speed_10m";
        var response = await client.GetFromJsonAsync<WeatherResponse>(url);

        if (response?.Current is null)
            return "Unable to retrieve weather data.";

        var c = response.Current;
        return $"Temperature: {c.Temperature}°C, Wind: {c.WindSpeed} km/h";
    }

    [McpServerTool, Description("Look up coordinates for a city name.")]
    public async Task<string> GeocodeCity(
        [Description("City name to look up")] string city)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";
        var response = await client.GetFromJsonAsync<GeocodeResponse>(url);

        if (response?.Results is not { Count: > 0 })
            return $"No results found for '{city}'.";

        var r = response.Results[0];
        return $"{r.Name} ({r.Country}): lat={r.Latitude}, lon={r.Longitude}";
    }
}

// --- JSON models for the Open-Meteo API ---

public record WeatherResponse
{
    [JsonPropertyName("current")]
    public CurrentWeather? Current { get; init; }
}

public record CurrentWeather
{
    [JsonPropertyName("temperature_2m")]
    public double Temperature { get; init; }

    [JsonPropertyName("wind_speed_10m")]
    public double WindSpeed { get; init; }
}

public record GeocodeResponse
{
    [JsonPropertyName("results")]
    public List<GeoResult>? Results { get; init; }
}

public record GeoResult
{
    [JsonPropertyName("name")]
    public string Name { get; init; } = "";

    [JsonPropertyName("country")]
    public string Country { get; init; } = "";

    [JsonPropertyName("latitude")]
    public double Latitude { get; init; }

    [JsonPropertyName("longitude")]
    public double Longitude { get; init; }
}

